// Register is the resolver for the register field.
func (r *mutationResolver) Register(ctx context.Context, email string, password string) (*model.AuthPayload, error) {
	hashed, err := auth.HashPassword(password)
	if err != nil {
		return nil, err
	}

	id := uuid.New().String()
	_, err = r.DB.Exec(`INSERT INTO users (id, email, password_hash) VALUES ($1,$2,$3)`, id, email, hashed)
	if err != nil {
		return nil, err
	}

	token, err := auth.GenerateJWT(id, 24*time.Hour)
	if err != nil {
		return nil, err
	}

	return &model.AuthPayload{
		Token: token,
		User: &model.User{
			ID:        id,
			Email:     email,
			Role:      "user",
			CreatedAt: time.Now(),
		},
	}, nil
}

// Login is the resolver for the login field.
func (r *mutationResolver) Login(ctx context.Context, email string, password string) (*model.AuthPayload, error) {
	var id, pwHash string
	if err := r.DB.QueryRowx(`SELECT id, password_hash FROM users WHERE email=$1`, email).Scan(&id, &pwHash); err != nil {
		return nil, err
	}

	if err := auth.CompareHashAndPassword(pwHash, password); err != nil {
		return nil, err
	}

	token, err := auth.GenerateJWT(id, 24*time.Hour)
	if err != nil {
		return nil, err
	}

	var createdAt time.Time
	_ = r.DB.Get(&createdAt, "SELECT created_at FROM users WHERE id=$1", id)

	return &model.AuthPayload{
		Token: token,
		User: &model.User{
			ID:        id,
			Email:     email,
			Role:      "user",
			CreatedAt: createdAt,
		},
	}, nil
}

