// CreateShare is the resolver for the createShare field.
func (r *mutationResolver) CreateShare(ctx context.Context, input model.ShareCreateInput) (*model.ShareCreatePayload, error) {
	userID, _ := ctx.Value("userID").(string)
	if userID == "" {
		return nil, fmt.Errorf("unauthenticated")
	}

	// validate ownership if fileId provided
	if input.FileID != nil {
		ownerID, err := db.GetFileOwnerID(ctx, r.DB.DB, *input.FileID)
		if err != nil {
			return nil, err
		}
		if ownerID != userID {
			return nil, fmt.Errorf("only uploader can share")
		}
	}

	// generate token
	token, err := crypto.GenerateShareToken(18)
	if err != nil {
		return nil, err
	}

	publicVal := true
	if input.Public != nil {
		publicVal = *input.Public
	}

	share := db.Share{
		FileID:       input.FileID,
		FolderID:     input.FolderID,
		OwnerID:      userID,
		Token:        token,
		Public:       publicVal,
		ExpiresAt:    input.ExpiresAt,
		MaxDownloads: input.MaxDownloads,
	}

	created, err := db.CreateShare(ctx, r.DB.DB, share)
	if err != nil {
		return nil, err
	}

	baseURL := os.Getenv("BASE_URL")
	if baseURL == "" {
		baseURL = "http://localhost:8080"
	}
	url := strings.TrimRight(baseURL, "/") + "/s/" + created.Token

	return &model.ShareCreatePayload{
		Token:     created.Token,
		URL:       url,
		ExpiresAt: created.ExpiresAt,
	}, nil
}

